import{_ as t,a as o}from"./chunks/3176b2becf2e994ce064.I2RTMoFM.js";import{_ as a,o as r,c as n,a5 as i}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"Self Improvers Are Creating Their Own Careers Online (Here’s How)","description":"","frontmatter":{"title":"Self Improvers Are Creating Their Own Careers Online (Here’s How)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/self-improvers-are-creating-their-own-career-heres-how.md","filePath":"en/letters/self-improvers-are-creating-their-own-career-heres-how.md"}'),s={name:"en/letters/self-improvers-are-creating-their-own-career-heres-how.md"};function l(p,e,h,u,c,d){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="self-improvers-are-creating-their-own-careers-online-here-s-how" tabindex="-1">Self Improvers Are Creating Their Own Careers Online (Here’s How) <a class="header-anchor" href="#self-improvers-are-creating-their-own-careers-online-here-s-how" aria-label="Permalink to &quot;Self Improvers Are Creating Their Own Careers Online (Here’s How)&quot;">​</a></h1><p>Dan Koe · 2023-04-07 · <a href="https://thedankoe.com/letters/self-improvers-are-creating-their-own-career-heres-how/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/self-improvers-are-creating-their-own-career-heres-how">返回中文译文</a></p><p>Wake up.</p><p>Hit snooze 4 times.</p><p>Stare at your phone.</p><p>Roll out of bed.</p><p>Make coffee.</p><p>Sit in traffic.</p><p>8 hours of unfulfilling work.</p><p>Sit in traffic… again.</p><p>Argue with your “significant” other.</p><p>Walk the pet.</p><p>Watch TV.</p><p>Pass out.</p><p>Repeat.</p><p>This should scare the shit out of you.</p><p>This is the state of 95% of the population.</p><p>Even those that are putting in effort on a daily basis to escape, can’t.</p><p>I did everything in my power to avoid a 9-5.</p><p>I built businesses from the age of 18 to 22 and didn’t make a penny. (But it was an incredibly fun way to spend my time).</p><p>When I did get a job, the list above was my assigned state of living.</p><p>I didn’t have control over how I structured 10 hours of my day.</p><p>Everything revolved around my work whether I wanted it to or not.</p><p>Over the past 3-4 years of my creator journey, I’ve realized a few things:</p><ul><li>Entrepreneurship is the only path for long-term logical thinkers</li><li>Humans have been removing labor work since the beginning of time (and we are on the horizon of complete removal)</li><li>The creator economy is the new economy. If you don’t have a personal brand you lose. Like that Black Mirror episode “Nosedive,” but in a good way.</li><li>Sensible people get paid for doing what they enjoy doing (shoutout Alan Watts for being ahead of his time).</li></ul><p>The future belongs to the self improver.</p><p>The person that takes responsibility for their future and becomes a fountain of value for those around them.</p><p>When done in public, it is almost impossible not to get paid.</p><p>That is what we are here to discuss today.</p><h2 id="entrepreneurship-is-overrated" tabindex="-1">“Entrepreneurship Is Overrated” <a class="header-anchor" href="#entrepreneurship-is-overrated" aria-label="Permalink to &quot;“Entrepreneurship Is Overrated”&quot;">​</a></h2><p>I was scrolling on YouTube the other day and a post caught my attention.</p><p>It asked, “What are things that everyone loves but you think are overrated?</p><p>There were comments about travel,</p><p>But this one caught my attention:</p><p><img src="'+t+'" alt=""></p><p><img src="'+o+'" alt=""></p><p>I won’t lie, it irked me at first.</p><p>How can people not realize that entrepreneurship is the only path to full control over your life?</p><p>And full control is the only path to sustainable enjoyment?</p><p>But it is becoming increasingly more difficult to find the “perfect” gig for you that allows you to consistently leverage all of the intrinsic drivers that make life good (curiosity, passion, purpose, autonomy, and mastery).</p><p>A few things hit me:</p><p><strong>People hate what they don’t understand.</strong></p><p>They only see 5% of an entrepreneur’s life and assume that’s enough to draw conclusions and close their mind. Curiosity vanishes at this moment.</p><p>They think entrepreneurship is overrated because they aren’t entrepreneurs.</p><p><strong>“I’m tired of</strong> <strong>being called</strong> <strong>a wage slave.”</strong></p><p>Sorry, but your feelings are not reality.</p><p>If you got let go and couldn’t pay your bills you are forced to work for your survival. You don’t have a choice. You are by definition a wage slave whether you like being called that or not.</p><p>Not only that, but most aren’t conscious of the exploitation that is going on behind the scenes. By staying at your predatory 9-5 you are enabling the exploitation of sweat shop workers and actively preventing human evolution. (Not in all cases, of course. Think through who you work for).</p><p><strong>“What’s wrong with me offering my skills to already developed corporations?”</strong></p><p>Nothing.</p><p>But why let the skills you acquire be influenced by a repetitive and income-capped career?</p><p>Why not lean into your unique interests and sell those skills to a developed corporation AS a business?</p><p>Then you aren’t a slave to certain productivity metrics, create your own systems, take on more clients, and make 5x what you would at the job with less work.</p><p>All of this, as always, is coming back to a narrow perspective enforced by a socially conditioned identity.</p><p>Or, they have a narrow view of what entrepreneurship is.</p><p><strong>“You’re paying a man $50 to escape the matrix, that’s not how it works.”</strong></p><p>I don’t care for Tate or his products, but $50 for time-tested marketable skills is better than a $40,000 outdated degree to get trained into the “matrix.”</p><p><strong>Entrepreneurs don’t go back to a 9-5.</strong></p><p>I’ve never heard of someone quitting a successful entrepreneurial venture to go back to a 9-5. But I hear of 9-5ers leaving their career for a better life all the time.</p><p><strong>“You’re busy all the time.”</strong></p><p>No, you aren’t.</p><p>The entire point of entrepreneurship is to reduce how much you work and prioritize the better things in life. If you are working all day, it’s not because you’re an entrepreneur, it’s because you lack self-management skills.</p><p>I work for <a href="https://thedankoe.com/the-4-hour-workday-focused-work-changed-my-life/" target="_blank" rel="noreferrer">4 hours a day</a> (most of the time) and cut myself off there. Because I know the quality of my work increases.</p><p><strong>The psychology of entrepreneurship.</strong></p><p>Our ancestors were entrepreneurs in their tribes.</p><p>And your psyche is not wired to remain stagnant.</p><p>You can do what you want, but I believe that the end goal for anyone is entrepreneurship.</p><p>Why? Because your psyche demands evolution for satisfaction. It demands an ever-increasing challenge without actually “winning the game.”</p><p>In a corporate power ladder, you will inevitably reach a point where challenge ceases to exist. You become docile, comfortable, and get used to mediocre living (and you will <em>think</em> that’s how it’s supposed to be).</p><p>The profound and meaningful lie in the unknown and entrepreneurship is your submarine into the depths of the ocean.</p><p><strong>Work consumes about 25% of your life.</strong></p><p>If you don’t create a career, you will be assigned one.</p><p>If you aren’t passionate about your work, you aren’t passionate for 25% of your life. Most people aren’t passionate about the other 75% of their life either.</p><p>Our career, or purpose, or mission is how we engage our attention with reality in an impactful way. It keeps us from going insane.</p><p>And frankly, we can’t engage our attention with the breath, body, or nature for our entire lives as a mindfulness practice. There must be a balance, but our attention must be engaged with reality to prevent a chaotic state of mind.</p><p>A 9-5 is a stepping stone.</p><p>I have nothing against a 9-5, but it is a means, not an end.</p><p>Use your job to acquire skills, knowledge, and status that allow you to create what you want.</p><h2 id="the-dissolution-of-labor" tabindex="-1">The Dissolution Of Labor <a class="header-anchor" href="#the-dissolution-of-labor" aria-label="Permalink to &quot;The Dissolution Of Labor&quot;">​</a></h2><blockquote><p>The real AI singularity, if it happens at all, isn&#39;t going to look like a sudden doomsday scenario like in a sci-fi story. The real way it happens—and this is probably inevitable—is as a gradual erosion of human labor <a href="https://t.co/gHXoKjZjfk" target="_blank" rel="noreferrer">pic.twitter.com/gHXoKjZjfk</a></p><p>— Zero HP Lovecraft 🦅🐍 (@0x49fa98) <a href="https://twitter.com/0x49fa98/status/1643016730187386880?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 3, 2023</a></p></blockquote><p>Aristotle condemned manual labor as harmful to the body and soul.</p><p>The Ancient Greeks saw work as a necessary part of life. But only as a means to leisure, creativity, and contemplation as they considered them the keys to happiness.</p><p>Without work, leisure loses its meaning and vice versa.</p><p>Life begins to lack balance and contrast.</p><p>Manual work isn’t always bad. But completing mindless tasks for the sake of survival or status makes you no different than a robot or animal.</p><p>A sense of mastery must uphold our endeavors to create meaningful work.</p><p>Your purpose is the source of suffering you accept.</p><p>First, there were slaves that were assigned most of the labor work.</p><p>Then, tools like tractors, windmills, and self-checkouts reduced the burden further.</p><p>Now, the majority of employees are tied to their cubicles to perform repetitive tasks that go against their nature.</p><p>My beliefs are that humanity has evolved to the point of not needing humans to perform the “dirty work.”</p><p>Automation and artificial intelligence have seen leaps in development over the years.</p><p>There have been many doomsday speculations on this, but I only see good coming from it.</p><p>A decline in labor work demands an incline in creative and knowledge work.</p><p>From McKenna: <em>“Thought can only go as far as the language that paves the road”</em></p><p>If we want to expand the limits of what’s possible, we have to create the knowledge, ideas, and beliefs that permeate culture and influence language. That way, collective thought can expand and exponential progress can be made.</p><p>The future of work, in my eyes, belongs to the creative.</p><p>The writers.</p><p>The speakers.</p><p>The designers.</p><p>The creators.</p><p>Every person that we thought AI would “replace.”</p><p>Instead, AI will act as a tool that allows creatives to push the boundaries.</p><p>To do this well, work is necessary, but rest and leisure are of more importance because of the brains Default Mode Network:</p><blockquote><p>“The DMN is a series of interconnected sections that activate as soon as people stop concentrating on external tasks, and shifts from outward-focused to inward-focused cognition.”</p></blockquote><p>In short, the brain is MORE active when you aren’t focused on work.</p><p>When we, as humans, prioritize both work and rest (not red wine and bubble baths type rest, but gym and walks type rest), we prime our mind for novel ideas.</p><p>And through the power of the internet, collective knowledge increases, and our capacity for thought evolves with it.</p><p>To get practical:</p><p>You now have the opportunity to pursue meaningful work that unlocks the parts of the brain that modern society has neglected for so long.</p><p>Humans can explore reality with passion, improve their skill set, and self-actualize.</p><p>The future of work belongs to the self-reliant, self-educated, and those that pursue the creative opportunity that automation and AI have presented.</p><p>The future is about balance, not overwork.</p><p>The future is about being human, not robotic.</p><p>The <a href="https://thedankoe.com/become-a-digital-renaissance-man-and-join-the-new-rich/" target="_blank" rel="noreferrer">digital renaissance</a> is here.</p><h2 id="the-creator-economy-is-the-new-economy" tabindex="-1">The Creator Economy Is The New Economy <a class="header-anchor" href="#the-creator-economy-is-the-new-economy" aria-label="Permalink to &quot;The Creator Economy Is The New Economy&quot;">​</a></h2><p>I’ve been talking about this for a while now, but <a href="https://twitter.com/themattmic" target="_blank" rel="noreferrer">Matt Mic</a> wrote an incredible thread that brings an entirely new perspective to my theory.</p><p>My theory = <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">the future of work and education</a> will be that every individual will have their own creator business (or work for creators) that act as a public school.</p><p>I’m going to summarize points from Matt’s thread with my own commentary and structure, <a href="https://twitter.com/themattmic/status/1643236796522700801" target="_blank" rel="noreferrer">but you can read it here.</a></p><p>First, we need to step back and realize how important social media is.</p><p>It can be toxic, yes, but that is a reflection of the individual’s choice to consume that content. Social media is an incredible addition to my life (and most creators’ lives, it is rarely toxic).</p><p>Humans are social creatures. Social media removes the barriers to socialization through media.</p><p>Media is how we learn.</p><p>Media is how we get new information.</p><p>Media is how we communicate the value of our businesses.</p><p>Media consumes a large portion of our lives. It creates a social fabric that people rely on for civilization to operate as it does.</p><p>P.S. I teach all of this, with Notion templates and systems, in <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>. It is a masterclass on creator brand, content, product creation, and promotions for the future.</p><h3 id="the-3-layers-of-social-media" tabindex="-1">The 3 Layers Of Social Media <a class="header-anchor" href="#the-3-layers-of-social-media" aria-label="Permalink to &quot;The 3 Layers Of Social Media&quot;">​</a></h3><p>Platforms form the first layer of digital media.</p><p>Apple and Google created the majority of the tech we hold in our hands and have in our offices. They laid the foundation for social media.</p><p>The second layer is apps like Facebook, Instagram, YouTube, and Twitter.</p><p>These apps captured the same value as the platform layer in that they have billions of monthly active users and trillions of dollars in value.</p><p>Over the past decade, a new and 3rd layer has emerged:</p><p>The Creator.</p><p>Like the apps themselves, huge creators like Rogan will garner billions of followers (over the next decade) and generate trillions of dollars.</p><p>Creators are “atomizing” what the social networks did by capturing mass attention, forming communities, distributing media, and generating revenue.</p><h3 id="the-need-for-human" tabindex="-1">The Need For Human <a class="header-anchor" href="#the-need-for-human" aria-label="Permalink to &quot;The Need For Human&quot;">​</a></h3><p>With automation and AI seeing exponential growth, it only makes sense that people will get their media fix from humans.</p><p>Personal brands.</p><p>People that educate, entertain, and inspire according to their interests.</p><p>Unless we rewrite the collective psyche (which hasn’t changed much in a few hundred years) then this is inevitable. People are attracted to people, not robots.</p><p>Robots have their place in decreasing labor and increasing human creativity, though.</p><h3 id="my-philosophy" tabindex="-1">My Philosophy <a class="header-anchor" href="#my-philosophy" aria-label="Permalink to &quot;My Philosophy&quot;">​</a></h3><p>Business is an extension of the self.</p><p>It is a vessel for your purpose.</p><p>Your purpose evolves, and you must solve the superficial problems in your life to reach your deepest purpose.</p><p>The pattern here are the eternal markets (where the most money flows).</p><p>Health, wealth, and relationships.</p><p>Solve your own problems by acquiring the skill and knowledge necessary to do so through the internet.</p><p>Pass down what you learn in the form of free content and paid products.</p><p>By doing so, you not only create an independent income source, but massive social leverage.</p><p>I’ve written about this extensively, but the most organized place to get the information is from the <a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4" target="_blank" rel="noreferrer">One Person Business series</a> on my YouTube.</p><h2 id="creator-monetization-methods" tabindex="-1">Creator Monetization Methods <a class="header-anchor" href="#creator-monetization-methods" aria-label="Permalink to &quot;Creator Monetization Methods&quot;">​</a></h2><p>Once you’ve <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">built an audience</a>, or even if you haven’t, there are many ways to monetize, but I will list them out by priority here.</p><h3 id="_1-freelancing-coaching-or-tutoring" tabindex="-1">1) Freelancing, Coaching, or Tutoring <a class="header-anchor" href="#_1-freelancing-coaching-or-tutoring" aria-label="Permalink to &quot;1) Freelancing, Coaching, or Tutoring&quot;">​</a></h3><p>To monetize from the start, you need a service.</p><p>Building a digital product or membership or software isn’t sustainable when you don’t have ample traffic to pull in an income.</p><p>When you create a minimum viable offer for $500-$1000, you can use direct outreach strategies to sell your offer.</p><p>Once you get some results and increase your prices you only need 2-3 clients a month to pull in more than the average US salary.</p><p>You don’t need a large audience and 500 product sales a month to generate an income.</p><p>What service do you create? I wrote about creating a <a href="https://thedankoe.com/the-best-online-business-model-to-make-1-million-in-2023/" target="_blank" rel="noreferrer">minimum viable offer</a> here.</p><p>In short, improve yourself and build something you would have wanted on your journey.</p><p>Pull inspiration from the products you purchased to achieve your self actualization.</p><p>Then, help others do the same.</p><h3 id="_2-cohorts-courses" tabindex="-1">2) Cohorts &amp; Courses <a class="header-anchor" href="#_2-cohorts-courses" aria-label="Permalink to &quot;2) Cohorts &amp; Courses&quot;">​</a></h3><p>Once you have a small audience and client results, you can transfer those results into a cohort style course.</p><p>This way, you can still:</p><ul><li>Charge higher prices</li><li>Maintain a sustainable income</li><li>Not need a ton of customers</li></ul><p>A cohort-based course is a regular course with a time frame, helpful group calls, and a community to answer questions.</p><p>Then, when the time is right and you have a larger audience, you can turn it into a full-fledged do-it-yourself course.</p><h3 id="_3-build-whatever-you-want" tabindex="-1">3) Build Whatever You Want <a class="header-anchor" href="#_3-build-whatever-you-want" aria-label="Permalink to &quot;3) Build Whatever You Want&quot;">​</a></h3><p>Now that you have distribution and leverage, you can sell anything you want really.</p><ul><li>Want to start a clothing brand? Feel free.</li><li>Want to sell a physical product like a supplement line? All you.</li><li>Want to drop everything and build a physical gym or coffee shop? Go ahead.</li></ul><p>You have the resources to make any business model work.</p><p>Your reputation is high. You have social capital. And your digital products are pulling in $50,000 to $200,000 a month.</p><p>This is on a 3-4 year time scale of course.</p><p>And just like that, you create your own career.</p><p>By learning, creating, and selling on the digital marketplace, you remove the barriers that once existed in the physical world.</p><p>The future is bright, and anyone that wants to take advantage has the ability to do so.</p><p>The eternal markets in business are:</p><ul><li>Health</li><li>Wealth</li><li>Relationships</li><li>Happiness</li></ul><p>These are all burning evergreen problems that people will face until the end of time.</p><p>Solve your own problems.</p><p>Document the solution.</p><p>Give it to others.</p><p>Get paid.</p><p>– Dan Koe</p>',187)])])}const g=a(s,[["render",l]]);export{y as __pageData,g as default};
